WITH lessons(code,year_label,source_key,title,goal) AS (VALUES
('NBEN01A01','1º Ano','src/escola-brilha/ingles-1ano/u1-a01-hello/data.ts','Hello!','Compreender e usar cumprimentos e apresentação simples com fala opcional.'),
('NBEN01A02','1º Ano','src/escola-brilha/ingles-1ano/u1-a02-hello-friend/data.ts','Hello, my friend','Reconhecer expressões de amizade e interação respeitosa em diálogos curtos.'),
('NBEN01A03','1º Ano','src/escola-brilha/ingles-1ano/u1-a03-colors/data.ts','My colors everywhere','Nomear e identificar cores com símbolos e formas que não dependam apenas da visão cromática.'),
('NBEN01A04','1º Ano','src/escola-brilha/ingles-1ano/u1-a04-passport/data.ts','English passport','Revisar cumprimentos, nomes e cores em uma jornada totalmente fictícia.'),
('NBEN01A05','1º Ano','src/escola-brilha/ingles-1ano/u1-a05-school/data.ts','My school','Reconhecer objetos e ações escolares sem pedir dados da escola real.'),
('NBEN01A06','1º Ano','src/escola-brilha/ingles-1ano/u1-a06-body/data.ts','My body','Nomear partes do corpo com dignidade, sem comparação física ou toque obrigatório.'),
('NBEN01A07','1º Ano','src/escola-brilha/ingles-1ano/u1-a07-world/data.ts','English around the world','Integrar vocabulário inicial reconhecendo diferentes países, línguas e sotaques.'),
('NBEN02A01','2º Ano','src/escola-brilha/ingles-2ano/u2-a01-routine/data.ts','My daily routine','Compreender ações cotidianas usando personagem e rotina fictícios.'),
('NBEN02A02','2º Ano','src/escola-brilha/ingles-2ano/u2-a02-house/data.ts','My house','Nomear espaços e objetos de moradias diversas sem expor a casa real.'),
('NBEN02A03','2º Ano','src/escola-brilha/ingles-2ano/u2-a03-food/data.ts','Food time','Comunicar preferências alimentares sem julgamento, dieta ou obrigação de revelar hábitos.'),
('NBEN02A04','2º Ano','src/escola-brilha/ingles-2ano/u2-a04-clothes/data.ts','Clothes and weather','Relacionar roupas e clima sem comentários sobre corpo, gênero ou condição econômica.'),
('NBEN02A05','2º Ano','src/escola-brilha/ingles-2ano/u2-a05-community/data.ts','My community','Reconhecer lugares e serviços em comunidade fictícia sem endereço ou rota real.'),
('NBEN02A06','2º Ano','src/escola-brilha/ingles-2ano/u2-a06-hobbies/data.ts','Hobbies and sports','Expressar interesses com alternativas motoras e sem competição obrigatória.'),
('NBEN02A07','2º Ano','src/escola-brilha/ingles-2ano/u2-a07-world/data.ts','Around the world','Integrar frases simples sobre rotina, casa, comida, roupa, comunidade e interesses.'),
('NBEN03A01','3º Ano','src/escola-brilha/ingles-3ano/u3-a01-welcome/data.ts','Welcome to my world','Apresentar personagem fictício usando repertório pessoal básico sem exposição real.'),
('NBEN03A02','3º Ano','src/escola-brilha/ingles-3ano/u3-a02-school/data.ts','My amazing school','Descrever disciplinas, objetos e espaços de escola fictícia.'),
('NBEN03A03','3º Ano','src/escola-brilha/ingles-3ano/u3-a03-healthy/data.ts','My healthy life','Compreender vocabulário de cuidados e hábitos sem prescrição, dieta ou julgamento corporal.'),
('NBEN03A04','3º Ano','src/escola-brilha/ingles-3ano/u3-a04-animals/data.ts','Animals around the world','Descrever animais, habitats e características com apoio multimodal.'),
('NBEN03A05','3º Ano','src/escola-brilha/ingles-3ano/u3-a05-city/data.ts','My city','Localizar lugares em mapa fictício sem geolocalização ou trajeto pessoal.'),
('NBEN03A06','3º Ano','src/escola-brilha/ingles-3ano/u3-a06-travel/data.ts','Time to travel','Planejar viagem imaginária sem documentos, localização ou experiência familiar.'),
('NBEN03A07','3º Ano','src/escola-brilha/ingles-3ano/u3-a07-adventure/data.ts','English adventure','Integrar vocabulário e estruturas do ano em desafio acessível e cooperativo.'),
('NBEN04A01','4º Ano','src/escola-brilha/ingles-4ano/u4-a01-friends/data.ts','My life and my friends','Descrever personagens, relações e preferências sem exigir informações familiares ou sociais reais.'),
('NBEN04A02','4º Ano','src/escola-brilha/ingles-4ano/u4-a02-school/data.ts','School projects','Planejar projeto escolar fictício usando colaboração e funções flexíveis.'),
('NBEN04A03','4º Ano','src/escola-brilha/ingles-4ano/u4-a03-healthy/data.ts','Healthy habits','Interpretar linguagem de autocuidado sem dieta, diagnóstico ou comparação corporal.'),
('NBEN04A04','4º Ano','src/escola-brilha/ingles-4ano/u4-a04-nature/data.ts','Amazing nature','Descrever ambientes e relações ecológicas com vocabulário contextualizado.'),
('NBEN04A05','4º Ano','src/escola-brilha/ingles-4ano/u4-a05-city/data.ts','Around my city','Dar e compreender direções em cidade fictícia sem rota ou localização real.'),
('NBEN04A06','4º Ano','src/escola-brilha/ingles-4ano/u4-a06-holidays/data.ts','Holidays and adventures','Comparar celebrações e viagens com respeito cultural e sem expor crença ou renda.'),
('NBEN04A07','4º Ano','src/escola-brilha/ingles-4ano/u4-a07-challenge/data.ts','English challenge','Organizar portfólio fictício e demonstrar compreensão por múltiplos formatos.'),
('NBEN05A01','5º Ano','src/escola-brilha/ingles-5ano/u5-a01-dreams/data.ts','My life, my story','Criar narrativa de personagem sobre planos e experiências sem exposição pessoal.'),
('NBEN05A02','5º Ano','src/escola-brilha/ingles-5ano/u5-a02-world/data.ts','Amazing places','Comparar lugares por fontes e imagens sem rastrear localização.'),
('NBEN05A03','5º Ano','src/escola-brilha/ingles-5ano/u5-a03-science/data.ts','Healthy life and sports','Usar linguagem de saúde e esporte sem metas físicas, dieta ou desempenho obrigatório.'),
('NBEN05A04','5º Ano','src/escola-brilha/ingles-5ano/u5-a04-stories/data.ts','Science and discoveries','Ler e produzir explicações simples sobre descobertas com evidências.'),
('NBEN05A05','5º Ano','src/escola-brilha/ingles-5ano/u5-a05-planet/data.ts','Stories around the world','Comparar narrativas de diferentes contextos respeitando cultura e direitos autorais.'),
('NBEN05A06','5º Ano','src/escola-brilha/ingles-5ano/u5-a06-city/data.ts','Our planet','Argumentar sobre cuidado ambiental usando cenário coletivo e linguagem acessível.'),
('NBEN05A07','5º Ano','src/escola-brilha/ingles-5ano/u5-a07-mission/data.ts','English mission','Integrar repertório do ano em portfólio multimodal, privado e consentido.')
