INSERT INTO public.teacher_inclusive_lessons (source_lesson_key,source_version,codigo_bncc,title,school_stage,school_year,subject,knowledge_object,learning_goal,supported_profiles,teacher_pages,student_pages,answer_key,accessibility,source_fidelity_checked,pedagogical_reviewed,technical_reviewed,status,source_route)
SELECT source_key,'audit-2026-09-04',code,title,'fundamental_1',year_label,'Língua Inglesa','Currículo complementar NeuroBrilha · '||title,goal,ARRAY['tea','tdah','dislexia','deficiencia_intelectual','comunicacao','motora_escrita','sensorial_auditiva','sensorial_visual'],
jsonb_build_array(jsonb_build_object('title','Guia inclusivo de Inglês — '||code,'purpose',goal,'sections',jsonb_build_array(
 jsonb_build_object('heading','Alinhamento correto','content',jsonb_build_array('Esta aula é currículo complementar do NeuroBrilha para o 1º ao 5º ano; o identificador NBEN é interno e não deve ser apresentado como código BNCC.','Mantenha ligação com a aula-fonte e registre somente evidências pedagógicas necessárias.')),
 jsonb_build_object('heading','Compreensão antes da produção','content',jsonb_build_array('Apresente significado por imagem, objeto, gesto consentido, tradução curta e áudio regulável; depois modele som, palavra e frase.','Fala e repetição em público são opcionais. Aceite apontamento, seleção, ordenação, comunicação alternativa, áudio privado, digitação ou escrita.','Trate sotaques e variedades do inglês com respeito; avalie inteligibilidade e compreensão, não imitação de sotaque nativo.')),
 jsonb_build_object('heading','Privacidade, cultura e bem-estar','content',jsonb_build_array('Use nomes, famílias, casas, rotinas, cidades, viagens, escolas e perfis fictícios; nunca peça endereço, geolocalização, documento, foto de casa, rota, renda, religião, diagnóstico ou história familiar.','Temas de corpo, roupa, alimentação, saúde e esporte não podem gerar comparação corporal, dieta, meta física ou exposição de hábito pessoal.','Use áudio e textos autorizados, licenciados ou em domínio público conforme aplicável; não reproduza letras ou obras integrais protegidas.')),
 jsonb_build_object('heading','Critério','content','Compreende quatro de cinco itens e comunica três significados por qualquer modo acessível, com apoio progressivamente reduzido.')))),
jsonb_build_array(jsonb_build_object('title','1. Compreender','instruction','Observe ou escute a palavra ou frase ligada a imagem, objeto ou cena fictícia.','activity','Associe três itens e identifique uma pista de significado.','support','Tradução curta, áudio repetível e regulável, legenda, imagem ampliada e tempo de processamento.'),jsonb_build_object('title','2. Construir','instruction','Organize cartões, símbolos ou palavras para formar significado.','activity','Complete ou monte duas frases sobre '||lower(title)||'.','support','Modelo resolvido, banco de palavras, código de cores combinado com rótulos e pistas graduadas.'),jsonb_build_object('title','3. Comunicar','instruction','Escolha como demonstrar compreensão sem fala pública obrigatória.','activity','Responda por seleção, gesto consentido, cartões, fala, áudio privado, digitação ou escrita.','support','Comunicação alternativa, leitor de tela, resposta privada e tecnologia assistiva.')),
jsonb_build_array(jsonb_build_object('page',1,'answer','Associa significado por pista visual, auditiva, tátil ou textual.'),jsonb_build_object('page',2,'answer','Constrói frases compreensíveis com apoio adequado ao ano.'),jsonb_build_object('page',3,'answer','Comunica significado no modo escolhido; variação de sotaque não é erro.','teacher_note','Registre compreensão, apoio eficaz e próximo passo; não registre voz, imagem, localização, saúde ou identidade pessoal.')),
jsonb_build_object('curriculum_alignment','neurobrilha_complementary_not_bncc','response_modes',jsonb_build_array('pointing','selection','cards','aac','oral_optional','private_audio','typing','writing','assistive_technology'),'routine','adjustable','one_instruction_at_a_time',true,'read_aloud',true,'captions',true,'large_text',true,'visual_schedule',true,'planned_pause',true,'audio_replay',true,'volume_control',true,'no_forced_speaking',true,'accent_dignity',true,'privacy_preserving',true,'fictional_personal_context',true,'no_live_geolocation',true,'no_family_disclosure',true,'no_health_disclosure',true,'body_neutral',true,'no_diet_or_fitness_target',true,'cultural_respect',true,'copyright_respect',true,'mobility_vision_hearing_inclusive',true,'print','grayscale-safe'),true,true,true,'published','/escola-brilha/ingles/'||lower(code) FROM lessons
ON CONFLICT (source_lesson_key,codigo_bncc) DO UPDATE SET source_version=EXCLUDED.source_version,title=EXCLUDED.title,school_stage=EXCLUDED.school_stage,school_year=EXCLUDED.school_year,subject=EXCLUDED.subject,knowledge_object=EXCLUDED.knowledge_object,learning_goal=EXCLUDED.learning_goal,supported_profiles=EXCLUDED.supported_profiles,teacher_pages=EXCLUDED.teacher_pages,student_pages=EXCLUDED.student_pages,answer_key=EXCLUDED.answer_key,accessibility=EXCLUDED.accessibility,source_fidelity_checked=EXCLUDED.source_fidelity_checked,pedagogical_reviewed=EXCLUDED.pedagogical_reviewed,technical_reviewed=EXCLUDED.technical_reviewed,status=EXCLUDED.status,source_route=EXCLUDED.source_route,updated_at=now();
