-- Biblioteca Inclusiva · Língua Inglesa do 8º ano completa.
WITH lessons(code,title,goal) AS (VALUES
('EF08LI01','Negociação de sentido','Esclarecer mal-entendidos por paráfrase, pergunta e confirmação em formatos acessíveis.'),
('EF08LI02','Opiniões com justificativa','Expressar e comparar pontos de vista com razões e evidências, sem exposição pessoal.'),
('EF08LI03','Recursos paralinguísticos','Interpretar pausas, entonação e expressão sem exigir contato visual ou gesto corporal.'),
('EF08LI04','Planos e previsões','Comunicar planos e previsões de personagens e cenários fictícios.'),
('EF08LI05','Sentido global em textos orais','Relacionar partes, assunto e informações relevantes em textos orais e multimodais.'),
('EF08LI06','Apreciação literária','Apreciar narrativas legalmente acessíveis, observando linguagem, cenário e efeitos no leitor.'),
('EF08LI07','Manifestações culturais','Comparar manifestações em inglês com contexto, autoria e respeito cultural.'),
('EF08LI08','Inferências e perspectivas','Inferir informações implícitas e comparar seleção de fatos, vozes e evidências.'),
('EF08LI09','Planejamento da escrita','Definir finalidade, público, gênero, suporte e recursos antes de escrever.'),
('EF08LI10','Revisão entre pares','Usar critérios objetivos para oferecer e receber retorno respeitoso, com alternativa privada.'),
('EF08LI11','Reconstrução e edição textual','Cortar, acrescentar, reformular e editar preservando autoria e sentido.'),
('EF08LI12','Produção sobre o futuro','Criar textos sobre futuros fictícios sem exigir projeto de vida ou dado pessoal.'),
('EF08LI13','Formação de palavras','Inferir e formar palavras com prefixos e sufixos em contexto.'),
('EF08LI14','Comparativos e superlativos','Comparar características e quantidades sem classificar pessoas ou corpos.'),
('EF08LI15','Quantificadores','Usar some, any, many e much conforme substantivos e contexto.'),
('EF08LI16','Pronomes relativos','Articular informações com who, which, that e whose, usando referentes claros.'),
('EF08LI17','Futuro e possibilidade','Distinguir be going to, will, may e might em planos, previsões e possibilidades.'),
('EF08LI18','Publicação responsável','Preparar produto final acessível sem postagem pública, nome real ou imagem identificável.'),
('EF08LI19','Comunicação intercultural','Investigar diferenças de sentido em gestos e expressões sem imitar identidades.'),
('EF08LI20','Prevenção de ruídos culturais','Perguntar, esclarecer e reparar mal-entendidos com respeito e sem generalizações.')
), normalized AS (
 SELECT code,'src/escola-brilha/ingles-8ano/bncc-workshops.ts'::text AS source_key,title,goal FROM lessons
)
